p.write_text('''def transform(grid):
 g=[r[:] for r in grid]; h=len(g); w=len(g[0]); bg=max(set(x for r in g for x in r),key=lambda x:sum(r.count(x) for r in g))
 for r in range(h):
  cs=[c for c in range(w) if g[r][c]!=bg]
  if len(cs)>=2:
   for c in range(min(cs)+1,max(cs)):
    if g[r][c]==bg:g[r][c]=2
 return g
''')
